/**
 * Utils
 * Part of "Data Grid Library"
 *
 * A collection of shared helper utilities used across the DataGrid ecosystem.
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

export class Utils {

    /**
     * English month names used for date formatting.
     * @returns {string[]}
     */
    static get monthNames() {
        return [
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        ];
    }

    /**
     * @param {DataGrid} grid - Reference to the parent DataGrid instance.
     */
    constructor(grid) {
        this.grid = grid;
        this._numberFormatter = null;
    }

    /**
     * Validate a time format (HH:MM, 24-hour).
     * @param {string} time
     * @returns {boolean}
     */
    isValidTimeFormat(time) {
        if (typeof time !== "string") return false;
        const TIME_REGEX = /^([01]\d|2[0-3]):([0-5]\d)$/;
        return TIME_REGEX.test(time);
    }

    /**
     * Validate date format (YYYY-MM-DD).
     * @param {string} date
     * @returns {boolean}
     */
    isValidDateFormat(date) {
        if (typeof date !== "string") return false;
        const DATE_REGEX = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
        return DATE_REGEX.test(date);
    }

    /**
     * Validate a date-time format (YYYY-MM-DD HH:MM:SS or HH:MM).
     * @param {string} dateTime
     * @returns {boolean}
     */
    isValidDateTimeFormat(dateTime) {
        if (typeof dateTime !== "string") return false;
        const DATETIME_REGEX = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])\s([01]\d|2[0-3]):([0-5]\d)(:([0-5]\d))?$/;
        return DATETIME_REGEX.test(dateTime);
    }

    /**
     * Validate email format.
     * @param {string} email
     * @returns {boolean}
     */
    isValidEmail(email) {
        if (typeof email !== "string") return false;
        const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return EMAIL_REGEX.test(email);
    }

    /**
     * Format a date string to "DD Month YYYY".
     * @param {string} val - Date string (YYYY-MM-DD).
     * @returns {string}
     */
    toDate(val) {
        if (!val) return "";
        const date = new Date(val);
        if (isNaN(date.getTime())) return "";
        const day = String(date.getDate()).padStart(2, "0");
        const month = Utils.monthNames[date.getMonth()];
        const year = date.getFullYear();
        return `${day} ${month} ${year}`;
    }

    /**
     * Format a datetime string to "DD Month YYYY HH:MM".
     * @param {string} val - Datetime string.
     * @returns {string}
     */
    toDateTime(val) {
        if (!val) return "";
        const date = new Date(val);
        if (isNaN(date.getTime())) return "";
        const day = String(date.getDate()).padStart(2, "0");
        const month = Utils.monthNames[date.getMonth()];
        const year = date.getFullYear();
        const hours = String(date.getHours()).padStart(2, "0");
        const minutes = String(date.getMinutes()).padStart(2, "0");
        return `${day} ${month} ${year} ${hours}:${minutes}`;
    }

    /**
     * Parses string values into native numbers, supporting both regional formats:
     * US/Global: 1,000.50 or EU/ID: 1.000,50
     * @param {*} val
     * @returns {number|*} Output numeric value, or input if unable to parse.
     */
    parseNumber(val) {
        if (typeof val === "number") return val;
        if (typeof val === "string") {
            let sanitized = val.trim();
            // Test for basic US format (e.g. 1,000.50)
            if (/^-?\d{1,3}(,\d{3})*(\.\d+)?$/.test(sanitized) || /^-?\d+(\.\d+)?$/.test(sanitized)) {
                sanitized = sanitized.replace(/,/g, '');
            }
            // Test for basic EU/ID format (e.g. 1.000,50)
            else if (/^-?\d{1,3}(\.\d{3})*(,\d+)?$/.test(sanitized) || /^-?\d+(,\d+)?$/.test(sanitized)) {
                sanitized = sanitized.replace(/\./g, '').replace(/,/g, '.');
            }
            
            const parsed = parseFloat(sanitized);
            return isNaN(parsed) ? val : parsed;
        }
        return val;
    }

    /**
     * Format numbers with a thousand separators.
     * @param {number|string} val
     * @returns {string}
     */
    toNumberFormat(val) {
        if (!this._numberFormatter) {
            this._numberFormatter = new Intl.NumberFormat('en-US');
        }
        const num = this.parseNumber(val);
        return typeof num !== "number" || isNaN(num) ? "0" : this._numberFormatter.format(num);
    }

    /**
     * Format boolean values as CoreUI badges.
     * @returns {string} HTML string.
     * @param val
     */
    toBoolean(val) {
        const truthy = ["true", "t", "1", true].includes(val);
        return truthy ? `<i class="cil-check-alt"></i>` : "-";
    }

    /**
     * Convert a string to a kebab-case.
     * @param {string} str
     * @returns {string}
     */
    toKebabCase(str) {
        if (typeof str !== "string") return "";
        return str
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/(^-|-$)/g, "");
    }

    /**
     * Create a DOM element with classes, attributes, and children.
     * @param {string} tag
     * @param {Object} options
     * @returns {HTMLElement}
     */
    createElement(tag, options = {}) {
        const el = document.createElement(tag);
        if (Array.isArray(options.classes)) {
            el.classList.add(...options.classes.filter(Boolean));
        }
        if (this.isObject(options.attributes)) {
            for (const [key, value] of Object.entries(options.attributes)) {
                el.setAttribute(key, value.toString());
            }
        }
        if (options.content) {
            el.innerHTML = options.content;
        }
        if (Array.isArray(options.children)) {
            options.children.forEach(child => {
                if (child instanceof Node) el.appendChild(child);
            });
        }
        return el;
    }

    /**
     * Create a standardized icon button.
     * @param {string} id
     * @param {string} title
     * @param {string} iconHtml
     * @param {string} [extraClass="btn-light"]
     * @returns {HTMLButtonElement}
     */
    buttonIcon(id, title, iconHtml, extraClass = "btn-light") {
        const btn = document.createElement("button");
        btn.id = id;
        btn.type = "button";
        btn.className = `btn btn-sm shadow-none border-0 ${extraClass}`;
        btn.dataset.coreuiToggle = "tooltip";
        btn.dataset.coreuiPlacement = "bottom";
        btn.title = title;
        btn.innerHTML = iconHtml;
        return btn;
    }

    /**
     * Remove an element from DOM by ID.
     * @param {string} id
     */
    removeElement(id) {
        const el = document.getElementById(id);
        if (el) el.remove();
    }

    /**
     * Dispose all active CoreUI tooltips.
     */
    disposeTooltips() {
        if (typeof coreui === "undefined" || !coreui.Tooltip) return;
        const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-coreui-toggle="tooltip"]'));
        tooltipTriggerList.forEach((el) => {
            // noinspection JSUnresolvedReference
            const existingTooltip = coreui.Tooltip.getInstance(el);
            if (existingTooltip) existingTooltip.dispose();
        });
    }

    /**
     * Initialize CoreUI tooltips on elements.
     */
    async triggerTooltips() {
        if (typeof coreui === "undefined" || !coreui.Tooltip) return;
        const tooltipTriggerList = [].slice.call(
            document.querySelectorAll('[data-coreui-toggle="tooltip"]')
        );

        tooltipTriggerList.forEach((el) => {
            // noinspection JSUnresolvedReference
            const existingTooltip = coreui.Tooltip.getInstance(el);
            if (existingTooltip) {
                existingTooltip.dispose();
            }
        });

        tooltipTriggerList.map((el) => {
            if (!el.title && !el.dataset.coreuiOriginalTitle) return;
            // noinspection JSUnresolvedReference
            return new coreui.Tooltip(el, {
                trigger: 'hover focus',
                boundary: 'window'
            });
        });
    }

    /**
     * Generate a random unique identifier.
     * @returns {string}
     */
    uniqueId() {
        return Math.random().toString(36).substring(2, 9);
    }

    /**
     * Deep clone an object with support for circular references and special types.
     * @param {*} obj - The object to clone.
     * @param {WeakMap} [hash=new WeakMap()] - Internal map to track circular references.
     * @returns {*}
     */
    deepClone(obj, hash = new WeakMap()) {
        if (obj === null || typeof obj !== "object") return obj;
        if (obj instanceof Date) return new Date(obj);
        if (obj instanceof RegExp) return new RegExp(obj);
        if (hash.has(obj)) return hash.get(obj);

        try {
            return structuredClone(obj);
        } catch (e) {
            const result = Array.isArray(obj) ? [] : {};
            hash.set(obj, result);
            for (const key in obj) {
                if (Object.prototype.hasOwnProperty.call(obj, key)) {
                    result[key] = this.deepClone(obj[key], hash);
                }
            }
            return result;
        }
    }

    /**
     * Type guard for objects.
     * @param {*} val
     * @returns {boolean}
     */
    isObject(val) {
        return val !== null && typeof val === "object" && !Array.isArray(val);
    }

    /**
     * Type guard for defined values.
     * @param {*} val
     * @returns {boolean}
     */
    isDefined(val) {
        return typeof val !== "undefined" && val !== null;
    }

    /**
     * Safe addition of numbers.
     * @param {*} a
     * @param {*} b
     * @returns {number}
     */
    add(a, b) {
        const x = Number(a);
        const y = Number(b);
        return (Number.isFinite(x) ? x : 0) + (Number.isFinite(y) ? y : 0);
    }

    /**
     * Safe division of numbers.
     * @param {*} a
     * @param {*} b
     * @returns {number}
     */
    divide(a, b) {
        const x = Number(a);
        const y = Number(b);
        if (!Number.isFinite(x) || !Number.isFinite(y)) {
            throw new TypeError("Arguments must be finite numbers");
        }
        if (y === 0) throw new Error("Division by zero");
        return x / y;
    }

    /**
     * Round a number to given precision.
     * @param {*} number
     * @param {number} precision
     * @returns {number}
     */
    round(number, precision = 0) {
        const n = Number(number);
        if (!Number.isFinite(n)) return 0;
        const factor = Math.pow(10, precision);
        return Math.round(n * factor) / factor;
    }

    /**
     * Normalize filter or sort priorities across columns.
     * @param {Array<Object>} columns
     * @param {"filter"|"sort"} type
     */
    normalizePriorities(columns, type = "filter") {
        const key = type === "filter" ? "filterPriority" : "sortPriority";

        const activeCols = columns.filter(col => {
            if (!col) return false;
            if (type === "filter") {
                return Array.isArray(this.grid.filter?.filteredItems?.[col.field])
                    && this.grid.filter.filteredItems[col.field].length > 0;
            } else {
                return col.sortDirection && col.sortDirection !== 0;
            }
        });

        activeCols.sort((a, b) => (a[key] || 0) - (b[key] || 0));

        activeCols.forEach((col, index) => {
            col[key] = index + 1;
        });

        columns.forEach(col => {
            if (!activeCols.includes(col)) {
                col[key] = 0;
            }
        });
    }

    /**
     * Normalizes a string into a valid and standardized DOM identifier or variable name.
     * 
     * The normalization process:
     * 1. Preserves existing underscores.
     * 2. Cleans Unicode characters (NFKD normalization).
     * 3. Removes all non-alphanumeric characters.
     * 4. Replaces dashes or whitespace with a single underscore.
     * 5. Ensures the string does not start with a digit (prefixes with an underscore if it does).
     * 6. Converts the final string to SCREAMING_SNAKE_CASE.
     *
     * @param {string} str - The raw string to be normalized.
     * @returns {string} The normalized, uppercase string suitable for DOM IDs or constants.
     */
    normalizeId(str) {
        if (!str) return "";
        return str
            .split(/(_+)/)
            .map(part => {
                if (/^_+$/.test(part)) return part;
                return part
                    .normalize("NFKD")
                    .replace(/[^a-zA-Z0-9-]/g, "")
                    .replace(/-+/g, "_");
            })
            .join("")
            .replace(/^(\d)/, "_$1")
            .toUpperCase();
    }
}