/**
 * Toolbar Module
 * Part of the "Data Grid Library".
 *
 * Provides top-level controls for the DataGrid, including
 * - Action buttons (Add, Export, Toolbox, Clear Sort/Filter, Column Settings)
 * - Global search input with debouncing
 * - CSV export based on the current grid state
 *
 * The toolbar operates on top of the existing grid state:
 * filters → global search → sorting
 *
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import DataGrid from "./DataGrid";

export class Toolbar {

    /**
     * Creates a Toolbar instance.
     *
     * @param {DataGrid} grid
     * Reference to the parent DataGrid instance.
     */
    constructor(grid) {
        this.grid = grid;
        this.uniqueId = this.grid.uniqueId;
        this.containerId = `datagrid-toolbar-${this.uniqueId}`;
        this._searchDebounce = null;
    }

    /**
     * Renders the toolbar UI into the target container.
     *
     * Layout:
     * - Left: Action buttons (Add, Export, etc.)
     * - Right: Global search input (if enabled)
     *
     * @async
     * @returns {Promise<void>}
     */
    async render() {
        const container = document.getElementById(this.containerId);
        if (!container) return;

        const row = document.createElement("div");
        row.className = "row g-1 align-items-center";

        const leftCol = document.createElement("div");
        leftCol.className = "col-auto d-flex flex-wrap gap-1 align-items-center";
        this._appendActionButtons(leftCol);

        const rightCol = document.createElement("div");
        rightCol.className = "col ms-auto";
        this._appendSearchInput(rightCol);

        row.append(leftCol, rightCol);
        container.replaceChildren(row);

        await this.grid.processData();
    }

    /**
     * Populates the action button group based on configuration flags.
     *
     * @private
     * @param {HTMLElement} container
     */
    _appendActionButtons(container) {
        const opt = this.grid.options;
        const utils = this.grid.utils;

        if (opt.canAdd) {
            const btn = utils.buttonIcon(`add-${this.uniqueId}`, "Add New", `<i class="cil-plus icon fw-bolder"></i>`);
            btn.onclick = () => typeof opt.addAction === "function" ? opt.addAction() : null;
            container.appendChild(btn);
        }

        if (opt.canExport) {
            const btn = utils.buttonIcon(`export-${this.uniqueId}`, "Export To CSV", `<i class="cil-description icon fw-bolder"></i>`);
            btn.onclick = () => this.exportToCSV();
            container.appendChild(btn);
        }

        if (opt.canToggleToolbox) {
            const btn = utils.buttonIcon(`toolbox-${this.uniqueId}`, "Toggle Toolbox", `<i class="cil-options icon fw-bolder"></i>`);
            btn.onclick = () => this.toggleToolbox();
            container.appendChild(btn);
        }

        if (opt.canClearSort) {
            const btn = utils.buttonIcon(`clear-sort-${this.uniqueId}`, "Clear All Sort", `<i class="cil-line-spacing icon fw-bolder"></i>`);
            btn.onclick = () => this.clearSort();
            container.appendChild(btn);
        }

        if (opt.canClearFilter) {
            const btn = utils.buttonIcon(`clear-filter-${this.uniqueId}`, "Clear All Filter", `<i class="cil-filter-x icon fw-bolder"></i>`);
            btn.onclick = () => this.clearFilter();
            container.appendChild(btn);
        }

        if (opt.canToggleColumn) {
            const btn = utils.buttonIcon(`column-settings-${this.uniqueId}`, "Column Settings", `<i class="cil-settings icon fw-bolder"></i>`);
            btn.onclick = () => this.grid.column.render();
            container.appendChild(btn);
        }
    }

    /**
     * Appends the global search input field if enabled.
     *
     * @private
     * @param {HTMLElement} container
     */
    _appendSearchInput(container) {
        if (!this.grid.options.canSearch) return;

        const wrapper = document.createElement("div");
        wrapper.className = "input-group input-group-sm";

        const input = document.createElement("input");
        input.type = "text";
        input.className = "form-control form-control-sm rounded-pill shadow-none px-3 border-light-subtle bg-light";
        input.placeholder = "Search...";
        input.value = this.grid.options.query || "";

        input.addEventListener("input", (e) => {
            clearTimeout(this._searchDebounce);
            /** @type {HTMLInputElement} */
            const target = e.target;
            this._searchDebounce = setTimeout(() => {
                this.grid.options.query = String(target.value || "").toLowerCase().trim();
                this.search();
            }, 300);
        });

        input.addEventListener("keydown", (e) => {
            if (e.key === "Escape") {
                this.grid.options.query = "";
                /** @type {HTMLInputElement} */
                const target = (e.target);
                target.value = "";
                this.search();
            }
        });

        wrapper.appendChild(input);
        container.appendChild(wrapper);
    }

    search() {
        this.grid.search(this.grid.options.query);
    }

    /**
     * Exports the current grid state to a CSV file.
     *
     * - Includes only visible columns.
     * - Respects current filters, search, and sort order.
     *
     * @returns {void}
     */
    exportToCSV() {
        const opt = this.grid.options;
        const columns = (opt.columns || []).filter(c => !c.hidden && c.field !== DataGrid.ACTION_COLUMN_ID);
        const records = this.grid.filteredRecords || [];

        const header = columns.map(c => `"${(c.title || c.field).replace(/"/g, '""')}"`).join(",");
        const rows = records.map(row => {
            return columns.map(col => {
                let val = row[col.field];
                if (val === null || val === undefined) val = "";
                return `"${String(val).replace(/"/g, '""')}"`;
            }).join(",");
        });

        const csvContent = [header, ...rows].join("\n");
        const blob = new Blob([csvContent], {type: "text/csv;charset=utf-8;"});
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");

        const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
        const name = opt.exportFilename || opt.name || opt.element?.id || "export";

        link.setAttribute("href", url);
        link.setAttribute("download", `${this.grid.utils.toKebabCase(name)}-${timestamp}.csv`);
        link.style.visibility = "hidden";
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    /**
     * Toggles the visibility of the header toolbox (sort/filter buttons).
     *
     * @returns {Promise<void>}
     */
    async toggleToolbox() {
        this.grid.options.showToolbox = !this.grid.options.showToolbox;
        await this.grid.records.renderHeader();
        if (this.grid.utils && typeof this.grid.utils.triggerTooltips === "function") {
            await this.grid.utils.triggerTooltips();
        }
        if (this.grid.filter && typeof this.grid.filter.updateButtonState === "function") {
            await this.grid.filter.updateButtonState();
        }
        if (this.grid.sort && typeof this.grid.sort.updateButtonState === "function") {
            this.grid.sort.updateButtonState();
        }
    }

    async clearSort() {
        (this.grid.options.columns || []).forEach(c => {
            c.sortDirection = 0;
            c.sortPriority = 0;
        });
        await this.grid.processData();
    }

    /**
     * Clears all column-specific filters.
     *
     * @returns {void}
     */
    clearFilter() {
        if (this.grid.filter && typeof this.grid.filter.clear === "function") {
            this.grid.filter.clear().then();
        }
    }


}