/**
 * Records
 * Part of "Data Grid Library"
 *
 * Responsible for managing and rendering grid records:
 * - Initializes record indexes and internal maps
 * - Builds column summaries (SUM, COUNT, AVG)
 * - Renders table container, header, caption, body, and footer
 * - Handles cell formatting and special rendering cases
 *
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import DataGrid from "./DataGrid";

export class Records {

    /**
     * Creates an instance of Records.
     *
     * @param {DataGrid} grid - Reference to the parent DataGrid instance.
     */
    constructor(grid) {
        this.grid = grid;
        this.uniqueId = this.grid.uniqueId;
        this.containerId = `datagrid-body-${this.uniqueId}`;
    }

    /**
     * Initializes record structures, clones data to avoid mutation,
     * builds indexes, and calculates initial counts.
     *
     * @returns {Promise<void>} A promise that resolves when initialization is complete.
     */
    async initialize() {
        this.grid.options.columns = (this.grid.options.columns || []).map(col => ({
            ...col,
            sortDirection: col.sortDirection || 0,
            sortPriority: col.sortPriority || 0,
            filterable: col.filterable ?? true,
            hidden: col.hidden ?? false
        }));
        const sourceColumns = this.grid.utils.deepClone(this.grid.options.columns);
        const records = this.grid.utils.deepClone(this.grid.options.records);
        this.filteredRecords = [];
        this.recordsById = {};
        this.recordsByField = {};
        this.expandedRows = new Set();

        const indexField = this.grid.options.index || 'id';
        for (const row of records) {
            this.filteredRecords.push(row);
            if (row && typeof row[indexField] !== "undefined") {
                this.recordsById[row[indexField]] = row;
            }

            for (const column of sourceColumns) {
                const field = column?.field;
                if (field && field !== DataGrid.ACTION_COLUMN_ID) {
                    this._indexRecordValue(this.recordsByField, field, row);
                }
            }
        }

        this.totalRecords = Object.keys(this.recordsById).length;
    }

    /**
     * Stores record value by field and record ID for internal indexing.
     *
     * @private
     * @param {Object} target - The target index object.
     * @param {string} key - The field name key.
     * @param {Object} row - The record object containing data.
     */
    _indexRecordValue(target, key, row) {
        const indexField = this.grid.options.index || 'id';
        if (!target[key]) target[key] = {};
        if (row && typeof row[indexField] !== "undefined") {
            target[key][row[indexField]] = row[key];
        }
    }

    /**
     * Calculates summary values (SUM, COUNT, AVG) for columns that have
     * a footer definition, based on the currently filtered records.
     *
     * @returns {Promise<void>} A promise that resolves when the summary is calculated.
     */
    async computeAggregates() {
        const utils = this.grid.utils;
        const columnSummaries = {};
        const columns = this.grid.options.columns || [];

        const records = Array.isArray(this.filteredRecords) ? this.filteredRecords : [];

        for (const column of columns) {
            const { footer, field } = column;
            if (!utils.isDefined(footer) || !field) continue;

            let sum = 0;
            let count = 0;
            let result = 0;

            for (const record of records) {
                const rawValue = record?.[field];
                const parsedValue = Number(rawValue);
                const finiteValue = Number.isFinite(parsedValue) ? parsedValue : 0;

                switch (footer) {
                    case DataGrid.AGGREGATION.SUM:
                        result = utils.add(result, finiteValue);
                        break;
                    case DataGrid.AGGREGATION.COUNT:
                        count++;
                        result = count;
                        break;
                    case DataGrid.AGGREGATION.AVG:
                        sum += finiteValue;
                        count++;
                        result = count > 0 ? utils.round(utils.divide(sum, count), 2) : 0;
                        break;
                    default:
                        break;
                }
            }

            columnSummaries[field] = Number(result) || 0;
        }

        this.columnSummaries = columnSummaries;
    }

    /**
     * Renders the grid table structure including container, header, body, and footer.
     * If the container already exists, it updates specific sections to optimize performance.
     *
     * @param {Array<Object>} [records=this.grid.filteredRecords] - The list of records to render.
     * @returns {Promise<void>} A promise that resolves when rendering is complete.
     */
    async render(records = this.grid.filteredRecords) {
        this.filteredRecords = records;

        const containerId = `table-container-${this.uniqueId}`;
        const existingContainer = document.getElementById(containerId);

        // Clean up Tooltip memory from native CoreUI instances
        if (this.grid.utils && typeof this.grid.utils.disposeTooltips === "function") {
            this.grid.utils.disposeTooltips();
        } else {
            const activeTooltips = document.querySelectorAll('.tooltip, .bs-tooltip-auto');
            activeTooltips.forEach(t => t.remove());
        }
        await this.computeAggregates();
        if (!existingContainer) {
            await this._renderContainer();
            await this.renderHeader();
        }
        await this.renderCaption();
        await this.renderBody();
        await this.renderFooter();
        setTimeout(() => {
            this.grid.utils.triggerTooltips();
        }, 0);
    }

    /**
     * Creates and appends the main table container element to the grid body.
     *
     * @returns {Promise<void>} A promise that resolves when the container is created.
     */
    async _renderContainer() {
        const containerId = `table-container-${this.uniqueId}`;
        const utils = this.grid.utils;
        utils.removeElement(containerId);
        const classes = ["table", "table-sm", "table-bordered", "border-light-subtle"];
        if (this.grid.options.stripedRows) {
            classes.push("table-striped");
        }
        if (this.grid.options.stripedColumns) {
            classes.push("table-striped-columns");
        }
        if (this.grid.options.hoverableRows) {
            classes.push("table-hover");
        }
        const table = utils.createElement("table", {
            classes: classes,
            attributes: { id: containerId },
        });

        const container = document.getElementById(this.containerId);
        if (!container) return;
        container.classList.add(...["px-2", "bg-white", "border-0"]);
        container.appendChild(table);
    }

    /**
     * Generates the table header (`thead`) including column titles,
     * sorting buttons, and filter buttons if enabled.
     *
     * @returns {Promise<void>} A promise that resolves when the header is created.
     */
    async renderHeader() {
        const containerId = "table-header-" + this.uniqueId;
        const utils = this.grid.utils;
        utils.removeElement(containerId);

        const showToolbox = this.grid.options.showToolbox;
        const showLineNumber = this.grid.options.showLineNumber;
        const container = utils.createElement("thead", { attributes: { id: containerId } });
        const firstRow = document.createElement("tr");

        if (this.grid.options.selectable) {
            const th = document.createElement("th");
            th.style.width = "40px";
            th.className = "text-center align-middle bg-white py-3";

            const checkAll = document.createElement("input");
            checkAll.type = "checkbox";
            checkAll.className = "form-check-input mt-0 pointer";

            checkAll.addEventListener("change", (e) => {
                /** @type {HTMLInputElement} */
                const target = (e.target);
                const isChecked = target.checked;
                const indexField = this.grid.options.index || 'id';
                this.grid.filteredRecords.forEach(rec => {
                    const id = String(rec[indexField]);
                    if (isChecked) {
                        this.grid.selectedRows.add(id);
                    } else {
                        this.grid.selectedRows.delete(id);
                    }
                });

                this.renderBody();
                if (typeof this.grid.options.onSelectRow === 'function') {
                    this.grid.options.onSelectRow(Array.from(this.grid.selectedRows));
                }
            });
            if (showToolbox) th.setAttribute("rowspan", "2");
            th.appendChild(checkAll);
            firstRow.appendChild(th);
        }

        if (showLineNumber) {
            const th = document.createElement("th");
            th.classList.add("text-center", "align-middle", "bg-white", "py-3", "text-nowrap");
            th.dataset.type = "string";
            th.style.width = "3%";
            if (showToolbox) th.setAttribute("rowspan", "2");
            th.textContent = "No";
            firstRow.appendChild(th);
        }

        const columns = this.grid.options.columns || [];
        for (const column of columns) {
            if (column.hidden) continue;
            const th = document.createElement("th");
            if (column.field === DataGrid.ACTION_COLUMN_ID) {
                th.style.width = "3%";
                th.classList.add("text-nowrap");
            }
            th.setAttribute("scope", "col");
            th.classList.add("text-center", "align-middle", "bg-white", "py-3", "px-3");
            th.dataset.type = typeof column.formatter === "string" ? column.formatter : "string";
            if (showToolbox && !(column.sortable || column.filterable)) {
                th.setAttribute("rowspan", "2");
            }
            th.innerHTML = column.title ?? "";
            firstRow.appendChild(th);
        }
        container.appendChild(firstRow);

        if (showToolbox) {
            const secondRow = document.createElement("tr");
            for (const column of columns) {
                if (column.hidden) continue;
                if (!(column.sortable || column.filterable)) continue;

                const th = document.createElement("th");
                if (column.field === DataGrid.ACTION_COLUMN_ID) {
                    th.style.width = "3%";
                    th.classList.add("text-nowrap");
                }
                th.setAttribute("scope", "col");
                th.classList.add("bg-white", "p-0");

                const wrapper = document.createElement("div");
                wrapper.classList.add("p-1", "hstack", "gap-1", "justify-content-center");

                if (column.sortable) {
                    const sortAscButton = utils.buttonIcon(
                        `sort-asc-${column.field}-${this.grid.uniqueId}`,
                        "Sort Asc",
                        `<i class="cil-sort-alpha-down icon fw-bolder"></i>`
                    );
                    sortAscButton.addEventListener("click", () => {
                        utils.disposeTooltips();
                        this.grid.sort.sort(column.field, 1);
                    });
                    wrapper.appendChild(sortAscButton);

                    const sortDescButton = utils.buttonIcon(
                        `sort-desc-${column.field}-${this.grid.uniqueId}`,
                        "Sort Desc",
                        `<i class="cil-sort-alpha-up icon fw-bolder"></i>`
                    );
                    sortDescButton.addEventListener("click", () => {
                        utils.disposeTooltips();
                        this.grid.sort.sort(column.field, -1);
                    });
                    wrapper.appendChild(sortDescButton);
                }

                if (column.filterable) {
                    const filterButton = utils.buttonIcon(
                        `filter-rows-${column.field}-${this.grid.uniqueId}`,
                        "Filter",
                        `<i class="cil-filter icon fw-bolder"></i>`
                    );
                    filterButton.addEventListener("click", () => this.grid.filter.render(column.field));
                    wrapper.appendChild(filterButton);
                }

                th.appendChild(wrapper);
                secondRow.appendChild(th);
            }
            container.appendChild(secondRow);
        }

        const tableContainer = document.getElementById("table-container-" + this.uniqueId);
        if (tableContainer) tableContainer.prepend(container);

        if (this.grid?.filter?.updateButtonState) {
            try {
                await this.grid.filter.updateButtonState();
            } catch (err) {
            }
        }
        if (this.grid?.sort?.updateButtonState) {
            try {
                this.grid.sort.updateButtonState();
            } catch (err) {
            }
        }
    }

    /**
     * Creates and updates the table caption, displaying entry counts,
     * active filters, and search query status.
     *
     * @returns {Promise<void>} A promise that resolves when the caption is created.
     */
    async renderCaption() {
        const containerId = "table-caption-" + this.uniqueId;
        const utils = this.grid.utils;
        utils.removeElement(containerId);

        const visibleColumns = (this.grid.options.columns || []).filter(v => !v.hidden);
        const columnsLength = visibleColumns.length + (this.grid.options.showLineNumber ? 1 : 0);

        let captionText = `Showing ${this.filteredRecords.length} of ${this.totalRecords} entries - ${columnsLength} column${columnsLength > 1 ? "s" : ""}`;

        const activeFilters = Object.entries(this.grid.filter?.filteredItems || {})
            .filter(([, arr]) => Array.isArray(arr) && arr.length > 0);
        if (activeFilters.length > 0) {
            captionText += ` | ${activeFilters.length} filter${activeFilters.length > 1 ? "s" : ""} active`;
        }

        const query = (this.grid.options.query || "").trim();
        if (query) {
            captionText += ` | search: "${query}"`;
        }

        const caption = this.grid.utils.createElement("caption", {
            attributes: { id: containerId },
            content: captionText,
        });

        const tableContainer = document.getElementById("table-container-" + this.uniqueId);
        if (tableContainer) tableContainer.appendChild(caption);
    }

    /**
     * Generates the table body (`tbody`) by iterating through filtered records.
     * Handles the creation of both master rows and optional detail rows.
     *
     * @returns {Promise<void>} A promise that resolves when the body is created.
     */
    async renderBody() {
        const containerId = "table-body-" + this.uniqueId;
        const utils = this.grid.utils;
        utils.removeElement(containerId);

        const columns = this.grid.options.columns || [];
        const records = this.filteredRecords || [];

        const container = document.createElement("tbody");
        container.setAttribute("id", containerId);
        container.classList.add("table-group-divider");
        container.addEventListener('click', (e) => {
            /** @type {HTMLElement} */
            const target = (e.target);
            const btn = target.closest('.btn-toggle-detail');
            if (btn) {
                e.stopPropagation();
                const rowId = btn.dataset.rowId;
                const action = btn.dataset.action || 'default';
                this.toggleExpandRow(rowId, action).catch(console.error);
            }
        });

        let visibleColCount = columns.filter(c => !c.hidden).length;
        if (this.grid.options.selectable) visibleColCount++;
        if (this.grid.options.showLineNumber) visibleColCount++;

        const rowsFragment = document.createDocumentFragment();
        let lineNumber = Number(this.grid.options.startLineNumber) || 1;
        const indexField = this.grid.options.index || 'id';
        for (const [, row] of records.entries()) {
            const rowId = row && typeof row[indexField] !== "undefined" ? row[indexField] : `r-${lineNumber}`;
            const trMaster = this.renderRow(row, rowId, lineNumber, columns);
            rowsFragment.appendChild(trMaster);

            if (this.grid.options.expandable && this.grid.expandedRows.has(String(rowId))) {
                const state = this.grid.expandedRows.get(String(rowId));
                const trDetail = this.renderDetailRow(row, rowId, visibleColCount, state.action);
                rowsFragment.appendChild(trDetail);
            }
            lineNumber++;
        }

        container.appendChild(rowsFragment);
        const tableContainer = document.getElementById("table-container-" + this.uniqueId);
        if (tableContainer) tableContainer.appendChild(container);
    }

    /**
     * Creates a single master row (`tr`) for the table body.
     *
     * @protected
     * @param {Object} row - The record object.
     * @param {string|number} rowId - The unique identifier for the row.
     * @param {number} lineNumber - The line number for the row.
     * @param {Array<Object>} columns - The list of column definitions.
     * @returns {HTMLTableRowElement} The constructed table row element.
     */
    renderRow(row, rowId, lineNumber, columns) {
        const tr = document.createElement("tr");
        tr.setAttribute("id", `${this.grid.element?.id ?? "grid"}__${rowId}__row`);
        tr.className = "align-middle border-bottom";

        const isDeleted = String(row?.is_deleted ?? "").toLowerCase();
        if (["t", "true", "1"].includes(isDeleted)) {
            tr.classList.add("is_deleted");
        }

        if (this.grid.options.selectable) {
            const tdSelect = document.createElement("td");
            tdSelect.className = "text-center align-middle p-2";

            const chkRow = document.createElement("input");
            chkRow.type = "checkbox";
            chkRow.className = "form-check-input mt-0 pointer";
            chkRow.checked = this.grid.selectedRows.has(String(rowId));
            chkRow.addEventListener("change", (e) => {
                const id = String(rowId);
                /** @type {HTMLInputElement} */
                const target = (e.target);
                if (target.checked) {
                    this.grid.selectedRows.add(id);
                } else {
                    this.grid.selectedRows.delete(id);
                }

                if (typeof this.grid.options.onSelectRow === 'function') {
                    this.grid.options.onSelectRow(Array.from(this.grid.selectedRows));
                }
            });

            tdSelect.appendChild(chkRow);
            tr.appendChild(tdSelect);
        }

        if (this.grid.options.showLineNumber) {
            const td = document.createElement("td");
            td.classList.add(...["text-center", "mw-100", "bg-white", "number", "text-nowrap"]);

            if (this.grid.options.expandable && this.grid.expandedRows.has(String(rowId))) {
                td.setAttribute("rowspan", "2");
                td.classList.add("align-top", "pt-2");
            }

            td.dataset.type = "number";
            td.textContent = this.grid.utils.toNumberFormat(lineNumber);
            tr.appendChild(td);
        }

        for (const column of columns) {
            if (column.hidden) continue;
            const td = this.renderCell(column, row);
            tr.appendChild(td);
        }

        return tr;
    }

    /**
     * Creates the detail row (`tr`) for master-detail views.
     * Initially hidden unless the row state is expanded.
     *
     * @protected
     * @param {Object} row - The record object.
     * @param {string|number} rowId - The unique identifier for the row.
     * @param visibleColCount
     * @param action
     * @returns {HTMLTableRowElement} The constructed detail row element.
     */
    renderDetailRow(row, rowId, visibleColCount, action) {
        const tr = document.createElement("tr");
        tr.id = `detail-row-${rowId}-${this.uniqueId}`;
        tr.className = "detail-row bg-light";

        const td = document.createElement("td");
        let adjustedColSpan = visibleColCount;
        if (this.grid.options.showLineNumber) {
            adjustedColSpan = visibleColCount - 1;
        }
        td.colSpan = adjustedColSpan;
        td.classList.add("p-2", "bg-body-tertiary");

        const wrapper = document.createElement("div");
        wrapper.className = "bg-light nested-grid-wrapper p-0 m-0";
        wrapper.id = this.grid.utils.normalizeId(`nested-container-${rowId}-${this.uniqueId}`);

        td.appendChild(wrapper);
        tr.appendChild(td);

        wrapper.addEventListener('transitionend', (e) => {
            if (e.propertyName === 'max-height' && wrapper.classList.contains('expanded')) {
                wrapper.style.maxHeight = 'none';
                wrapper.style.overflow = 'visible';
            }
        }, { once: true });

        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                wrapper.classList.add("expanded");
            });
        });

        if (typeof this.grid.options.onExpandRow === 'function') {
            this.grid.options.onExpandRow(rowId, wrapper, action, row);
        }

        return tr;
    }

    /**
     * @deprecated Use renderDetailRow instead. This will be removed in future versions.
     */
    onExpandRow(row, rowId, visibleColCount, action) {
        console.warn("DataGrid: Records.onExpandRow() is deprecated. Please use Records.renderDetailRow() instead.");
        return this.renderDetailRow(row, rowId, visibleColCount, action);
    }

    /**
     * Creates a single data cell (`td`) based on the column definition and row data.
     * Applies formatting, styles, and attributes.
     *
     * @param {Object} column - The column definition object.
     * @param {Object} row - The record object containing data.
     * @returns {HTMLTableCellElement} The constructed table cell element.
     */
    renderCell(column, row) {
        const { title, field, formatter, attributes } = column;
        const indexField = this.grid.options.index || 'id';
        const value = row ? row[field] : undefined;
        const td = document.createElement("td");
        td.setAttribute("id", `${this.grid.element?.id ?? "grid"}__${row[indexField]}__cell__${field}`);

        if (typeof title === "string" && title.length > 0 && field !== "A") {
            td.setAttribute("title", title.replace(/<\/?[^>]+(>|$)/g, " ").replace(/\s+/g, " ").trim());
        }

        td.setAttribute("scope", "row");
        td.dataset.type = typeof formatter === "string" ? formatter : "string";

        if (Array.isArray(column.styles) && column.styles.length > 0) {
            td.classList.add(...column.styles);
        } else if (typeof column.styles === "string" && column.styles.length > 0) {
            td.classList.add(column.styles);
        }
        if (!Array.from(td.classList).some(c => c.includes("align"))) {
            td.classList.add("align-middle");
        }

        if (field === DataGrid.ACTION_COLUMN_ID) {
            td.classList.add("text-center", "text-nowrap");
            if (typeof formatter === "function") {
                td.innerHTML = formatter(row);
            } else {
                td.innerHTML = "";
            }
            return td;
        }

        if (this.grid.utils.isObject(attributes)) {
            for (const key in attributes) {
                if (Object.prototype.hasOwnProperty.call(attributes, key)) {
                    td.setAttribute(key, attributes[key]);
                }
            }
        }

        if (typeof formatter === "function") {
            td.innerHTML = formatter(row);
            return td;
        }

        if (typeof formatter === "string") {
            switch (formatter) {
                case "date":
                    td.textContent = this.grid.utils.isValidDateFormat(value) ? this.grid.utils.toDate(value) : "";
                    break;
                case "time":
                    td.classList.add("text-center");
                    td.textContent = this.grid.utils.isValidTimeFormat(value) ? value : "";
                    break;
                case "datetime":
                    td.textContent = this.grid.utils.isValidDateTimeFormat(value) ? this.grid.utils.toDateTime(value) : "";
                    break;
                case "email":
                    td.textContent = this.grid.utils.isValidEmail(value) ? value : "";
                    break;
                case "boolean": {
                    const isTrue = String(value).toLowerCase() === 'true' || String(value).toLowerCase() === 't' || value === true || value === 1;
                    td.innerHTML = isTrue ? this.grid.utils.toBoolean(true) : this.grid.utils.toBoolean(false);
                    td.classList.add("text-center");
                    break;
                }
                case "number":
                case "float":
                    td.classList.add("text-end");
                    td.textContent = this.grid.utils.toNumberFormat(typeof value !== "undefined" ? value : 0);
                    break;
                case "html":
                    td.innerHTML = value ?? "";
                    break;
                default:
                    td.textContent = value ?? "";
                    break;
            }
            return td;
        }

        td.textContent = typeof value !== "undefined" && value !== null ? String(value) : "";
        return td;
    }

    /**
     * Renders the table footer containing column summaries (SUM, COUNT, AVG).
     * Only renders if at least one column has a footer aggregation defined.
     *
     * @async
     * @returns {Promise<void>} A promise that resolves when the footer is created.
     */
    async renderFooter() {
        const columns = this.grid.options.columns || [];
        const utils = this.grid.utils;
        const tableContainer = document.getElementById("table-container-" + this.uniqueId);

        const table = tableContainer?.tagName === 'TABLE' ? tableContainer : tableContainer?.querySelector('table');
        if (!table) return;

        const AGG = DataGrid.AGGREGATION;

        const hasAggregation = columns.some(col => col.footer && Object.values(AGG).includes(col.footer));

        if (!hasAggregation) {
            const existingFooter = table.querySelector('tfoot');
            if (existingFooter) existingFooter.remove();
            return;
        }

        let tfoot = table.querySelector('tfoot');
        if (!tfoot) {
            tfoot = document.createElement("tfoot");
            tfoot.className = "fw-bolder";
            table.appendChild(tfoot);
        }
        tfoot.innerHTML = "";

        const tr = document.createElement("tr");

        if (this.grid.options.selectable) {
            tr.appendChild(document.createElement("td"));
        }
        if (this.grid.options.showLineNumber) {
            tr.appendChild(document.createElement("td"));
        }

        for (const column of columns) {
            if (column.hidden) continue;

            const field = column.field;
            const value = this.columnSummaries ? this.columnSummaries[field] : undefined;
            const td = document.createElement("td");
            td.classList.add("text-end");

            if (column.footer && typeof value !== "undefined") {
                const numVal = Number(value);
                if (!isNaN(numVal)) {
                    const digits = (column.footer === AGG.COUNT || numVal % 1 === 0) ? 0 : 2;
                    td.textContent = utils.toNumberFormat(numVal.toFixed(digits));
                } else {
                    td.textContent = "0";
                }
            }
            tr.appendChild(td);
        }
        tfoot.appendChild(tr);
    }

    _cleanupChildGrids(containerElement) {
        if (!containerElement) return;
        const elements = containerElement.querySelectorAll('*');
        elements.forEach(el => {
            if (el.__dataGridInstance && typeof el.__dataGridInstance.destroy === 'function') {
                el.__dataGridInstance.destroy();
            }
        });
    }

    /**
     * Toggles the expansion state of a row in the grid.
     *
     * If the row is already expanded with the same action, it will be collapsed.
     * Otherwise, the row will be expanded with the specified action.
     *
     * @async
     * @param {string|number} rowId - The unique identifier of the row to toggle.
     * @param {string} action - The action associated with expanding the row.
     * @returns {Promise<void>} Resolves once the grid body has been re-rendered.
     */
    async toggleExpandRow(rowId, action) {
        if (this.grid.utils && typeof this.grid.utils.disposeTooltips === "function") {
            this.grid.utils.disposeTooltips();
        } else {
            const activeTooltips = document.querySelectorAll('.tooltip, .bs-tooltip-auto');
            activeTooltips.forEach(t => t.remove());
        }

        rowId = String(rowId);
        const expandedRows = this.grid.expandedRows;

        if (expandedRows.has(rowId) && expandedRows.get(rowId).action === action) {
            const wrapper = document.getElementById(`nested-container-${rowId}-${this.uniqueId}`);

            if (wrapper) {
                wrapper.classList.remove("expanded");
                await new Promise(resolve => setTimeout(resolve, 400));
                this._cleanupChildGrids(wrapper);
            }

            expandedRows.delete(rowId);
            await this.render();
            return;
        }

        if (expandedRows.has(rowId)) {
            const oldWrapper = document.getElementById(`nested-container-${rowId}-${this.uniqueId}`);
            if (oldWrapper) this._cleanupChildGrids(oldWrapper);
        }

        expandedRows.set(rowId, { action: action });
        await this.render();
    }
}