/**
 * Sort Module
 * Part of the "Data Grid Library".
 *
 * Responsible for handling column-based sorting, including:
 * - Single or multi-column sorting
 * - Sort priority and direction management
 * - Safe handling of null/undefined values
 * - UI state synchronization for sort buttons
 *
 * Refactored for safety, clarity, and robustness in 2025.
 *
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import DataGrid from "./DataGrid";

export class Sort {

    /**
     * Creates a Sort instance.
     *
     * @param {DataGrid} grid
     * Reference to the parent DataGrid instance.
     */
    constructor(grid) {
        /**
         * @type {DataGrid}
         * @private
         */
        this.grid = grid;
    }

    /**
     * Apply sorting to a specific column field.
     *
     * This method:
     * - Validates column existence and visibility
     * - Sets the target sort direction and priority
     * - Delegates sorting execution and UI updates to grid.processData()
     *
     * @async
     * @param {string} field
     * Column field name to be sorted.
     *
     * @param {number} direction
     * Sort direction: 1 for Ascending, -1 for Descending.
     *
     * @returns {Promise<void>}
     */
    async sort(field, direction) {
        try {
            const columns = this.grid.options?.columns || [];
            const col = columns.find(c => c.field === field);

            if (!col) return;
            if (col.hidden) {
                console.warn(`Sort ignored: column "${field}" is hidden.`);
                return;
            }

            col.sortDirection = parseInt(direction.toString());
            if (!col.sortPriority || col.sortPriority === 0) {
                const maxPriority = Math.max(0, ...columns.map(c => c.sortPriority || 0));
                col.sortPriority = maxPriority + 1;
            }

            this.grid.utils.normalizePriorities(columns, "sort");

            await this.grid.processData();

        } catch (err) {
            console.error("Sort error:", err);
        }
    }

    /**
     * Updates the visual state of sort buttons in the UI.
     *
     * This method:
     * - Resets all sort buttons to the default state-Activates the correct button based on a sort direction
     * - Safely skips invalid or hidden columns
     *
     * @returns {Promise<void>}
     */
    async updateButtonState() {
        const uniqueId = this.grid.uniqueId;
        const columns = this.grid.options?.columns || [];

        columns.forEach((col) => {
            if (!col) return;

            const {field, sortDirection} = col;

            if (
                !field ||
                field === DataGrid.ACTION_COLUMN_ID ||
                this.grid.columnsByField?.[field]?.hidden
            ) {
                return;
            }

            const ascBtn = document.getElementById(`sort-asc-${field}-${uniqueId}`);
            const descBtn = document.getElementById(`sort-desc-${field}-${uniqueId}`);

            const setDefault = (el) => {
                if (el) el.className = "btn btn-light btn-sm";
            };

            const setActive = (el) => {
                if (el) el.className = "btn btn-dark text-white btn-sm";
            };

            setDefault(ascBtn);
            setDefault(descBtn);

            if (sortDirection === 1) setActive(ascBtn);
            else if (sortDirection === -1) setActive(descBtn);
        });
    }
}