/**
 * JavaScript Data Grid Library
 *
 * Provides a modular, extensible data grid component with support for:
 * - Toolbar actions (add, export, search, toggle toolbox)
 * - Column visibility and configuration
 * - Record rendering (header, body, footer, summaries)
 * - Per-column filtering
 * - Single and multi-column sorting
 *
 * The DataGrid acts as the main orchestrator and shared state container
 * for all submodules (Toolbar, Column, Records, Filter, Sort).
 *
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import { Utils } from "./Utils.js";
import { Toolbar } from "./Toolbar.js";
import { Column } from "./Column.js";
import { Records } from "./Records.js";
import { Filter } from "./Filter.js";
import { Sort } from "./Sort.js";

export default class DataGrid {

    static ACTION_COLUMN_ID = "A";
    static AGGREGATION = { SUM: "__SUM__", COUNT: "__COUNT__", AVG: "__AVG__" };

    /**
     * Default configuration values for DataGrid.
     *
     * These values are shallow-merged with user-provided options
     * during construction.
     *
     * @type {Object}
     */
    static defaults = {
        index: "id",
        name: "",
        exportFilename: "",
        columns: [],
        records: [],
        serverSide: false, // Determines library state: Local Data (false) or Ajax/Server Side (true)
        url: null,
        fetchOptions: {
            method: "POST",
            body: (() => {
                const form = new FormData();
                form.append("a", "list_all");
                return form;
            })()
        },
        canAdd: true,
        canExport: true,
        canSearch: true,
        canToggleToolbox: true,
        canClearSort: true,
        canClearFilter: true,
        canToggleColumn: true,
        expandable: false,
        onExpandRow: null,
        selectable: false,
        onSelectRow: null,

        query: "",
        showToolbar: true,
        showToolbox: true,
        showLineNumber: true,
        startLineNumber: 1,

        hoverableRows: true,
        stripedRows: false,
        stripedColumns: false,

        addAction: () => {
        },
    };

    /**
     * Create a new DataGrid instance.
     *
     * Responsibilities:
     * - Resolve and validate the target DOM element-Merge configuration options with defaults
     * - Initialize shared state and utility helpers
     * - Instantiate all submodules
     * - Perform asynchronous initialization and initial rendering
     * - Seal the instance to prevent accidental property mutation
     *
     * @param {string|Element} element
     * Target container, either:
     * - A DOM Element
     * - A selector string (with or without leading '#')
     *
     * @param {Object} [options={}]
     * Custom configuration options overriding {@link DataGrid.defaults}.
     */
    constructor(element, options = {}) {

        this.utils = new Utils(this);

        const el = this._resolveElement(element);
        if (!el) {
            console.error("DataGrid: target element not found or invalid:", element);
            return;
        }

        this.element = el;
        if (this.element) {
            // If a DataGrid instance already exists on this element, destroy it first
            if (this.element.__dataGridInstance instanceof DataGrid) {
                this.element.__dataGridInstance.destroy();
            }
            this.element.__dataGridInstance = this;
        }
        this.uniqueId = this.utils.uniqueId();
        this.options = Object.assign({}, DataGrid.defaults, (options || {}));

        // Set Default URL to window.location.href
        if (!this.options.url) {
            this.options.url = window.location.href;
        }

        // Auto-detection mode fallback & explicitly distinguish condition
        if (typeof options.serverSide === 'undefined') {
            const hasExplicitUrl = typeof options.url !== 'undefined';
            const hasExplicitRecords = typeof options.records !== 'undefined';
            this.options.serverSide = hasExplicitUrl && !hasExplicitRecords;
        }

        if (!options || typeof options.columns === 'undefined') {
            this.options.columns = [...DataGrid.defaults.columns];
        }

        if (!options || typeof options.records === 'undefined') {
            this.options.records = [...DataGrid.defaults.records];
        }

        if (!options || typeof options.fetchOptions === 'undefined') {
            const defaultForm = new FormData();
            defaultForm.append("a", "list_all");
            this.options.fetchOptions = {
                method: DataGrid.defaults.fetchOptions?.method || "POST",
                body: defaultForm
            };
        } else {
            this.options.fetchOptions = {
                method: DataGrid.defaults.fetchOptions?.method || "POST",
                ...options.fetchOptions
            };
        }

        this.columnsByField = {}
        this.filteredRecords = [];
        this.toolbar = new Toolbar(this);
        this.column = new Column(this);
        this.records = new Records(this);
        this.filter = new Filter(this);
        this.sort = new Sort(this);
        this.expandedRows = new Map();
        if (this.element.id) {
            try {
                const id = this.element.id;
                const existingGlobal = window[id];

                if (existingGlobal && !(existingGlobal instanceof HTMLElement) && !(existingGlobal instanceof DataGrid)) {
                    throw new Error(`DataGrid Error: Variable 'window.${id}' is already defined by another script. Registration failed to prevent variable collision.`);
                }

                window[id] = this;
            } catch (err) {
                console.error(err.message || err);
            }
        }

        (async () => {
            try {
                await this.initialize();

                // Fetch data based on the configured serverSide mode
                const shouldFetch = this.options.serverSide === true;
                if (shouldFetch) {
                    this.options.records = await this.fetchRecords();
                }

                await this.records.initialize();
                await this.records.computeAggregates();

                this.filteredRecords = [...this.options.records];
                await this.toolbar.render();
                await this.render();
                if (this.utils && typeof this.utils.triggerTooltips === 'function') {
                    await this.utils.triggerTooltips();
                }
            } catch (err) {
                console.error("DataGrid initialization error:", err);
            }
        })();

        this.selectedRows = new Set();
        Object.seal(this);
    }



    /**
     * Resolve a target element from various input types.
     *
     * Supported inputs:
     * - `null` → returns null
     * - `Element` → returned as-is
     * - `string` → resolved using `querySelector`
     *
     * @private
     * @param {string|Element|null} element
     * Input element reference.
     *
     * @returns {Element|null}
     * Resolved DOM element or null if invalid.
     */
    _resolveElement(element) {
        if (!element) return null;

        if (element instanceof Element) {
            return element;
        }

        if (typeof element === "string") {
            const selector = element.startsWith("#")
                ? element
                : `#${element}`;
            return document.querySelector(selector);
        }

        return null;
    }

    /**
     * Initialize the base container structure for the DataGrid.
     *
     * This method:
     * - Applies layout and styling classes to the root container
     * - Creates standardized toolbar and body containers
     * - Replaces existing children with the grid layout
     *
     * @async
     * @returns {Promise<void>}
     */
    async initialize() {
        const { uniqueId, element } = this;
        element.classList.add(
            "datagrid",
            "row",
            "row-cols-1",
            "overflow-x-auto",
            "rounded-0",
            "m-0",
            "p-0"
        );

        const children = [];

        if (this.options.name) {
            const title = document.createElement("div");
            title.id = `datagrid-title-${uniqueId}`;
            title.className = "col bg-white border-bottom border-light-subtle fw-bold p-3";
            title.innerHTML = `${this.options.name}`;
            children.push(title);
        }

        const toolbar = document.createElement("div");
        toolbar.id = `datagrid-toolbar-${uniqueId}`;
        toolbar.className = "col bg-white p-3 rounded-0";
        children.push(toolbar);

        const body = document.createElement("div");
        body.id = `datagrid-body-${uniqueId}`;
        body.className = "col px-3 bg-white border-0 table-responsive  rounded-0";
        children.push(body);

        element.replaceChildren(...children);
    }

    /**
     * Helper to retrieve only the unique identifiers (IDs) of the selected rows.
     * @returns {Array<String|Number>} An array containing the selected row IDs.
     */
    getSelectedIds() {
        return Array.from(this.selectedRows || []);
    }

    /**
     * Retrieves the complete list of currently selected records (checked rows).
     * @returns {Array<Object>} An array containing the original data objects.
     */
    getSelectedRecords() {
        if (!this.options.selectable || !this.selectedRows || this.selectedRows.size === 0) {
            return [];
        }
        const indexField = this.options.index || 'id';
        return (this.options.records || []).filter(record => {
            const recordId = String(record[indexField]);
            return this.selectedRows.has(recordId);
        });
    }

    /**
     * Centralized data processing: Filter -> Search -> Sort -> Render.
     * This ensures consistent data processing across all modules.
     *
     * @async
     * @returns {Promise<void>}
     */
    async processData() {
        try {
            // 1. Start with master records
            let records = this.utils.deepClone(this.options.records || []);

            // 2. Apply Filters (from Filter module)
            const filteredItems = this.filter?.filteredItems || {};
            const activeFilters = Object.entries(filteredItems)
                .filter(([, values]) => Array.isArray(values) && values.length > 0);

            if (activeFilters.length > 0) {
                records = records.filter(record =>
                    activeFilters.every(([field, values]) => {
                        const rawValue = record[field];
                        const recordValue = rawValue === null || rawValue === undefined ? "" : String(rawValue);
                        return values.includes(recordValue);
                    })
                );
            }

            // 3. Apply Global Search (from Toolbar)
            const query = (this.options.query || "").trim().toLowerCase();
            if (query) {
                const searchColumns = (this.options.columns || []).filter(c => !c.hidden && c.field !== DataGrid.ACTION_COLUMN_ID);
                records = records.filter(record => {
                    return searchColumns.some(col => {
                        const val = record[col.field];
                        let formattedVal = "";

                        if (typeof col.formatter === "function") {
                            try {
                                formattedVal = String(col.formatter(record)).replace(/<[^>]*>?/gm, '');
                            } catch (e) {
                                formattedVal = "";
                            }
                        } else if (typeof col.formatter === "string") {
                            switch (col.formatter) {
                                case "date":
                                    formattedVal = this.utils.isValidDateFormat(val) ? this.utils.toDate(val) : "";
                                    break;
                                case "time":
                                    formattedVal = this.utils.isValidTimeFormat(val) ? String(val) : "";
                                    break;
                                case "datetime":
                                    formattedVal = this.utils.isValidDateTimeFormat(val) ? this.utils.toDateTime(val) : "";
                                    break;
                                case "number":
                                case "float":
                                    formattedVal = this.utils.toNumberFormat(typeof val !== "undefined" ? val : 0);
                                    break;
                                case "boolean": {
                                    const isTrue = String(val).toLowerCase() === 'true' || String(val).toLowerCase() === 't' || val === true || val === 1;
                                    // Based on utils.toBoolean which generates icons, we'll just use a generic representation or skip boolean search
                                    formattedVal = isTrue ? "true yes" : "false no";
                                    break;
                                }
                                default:
                                    formattedVal = val !== null && val !== undefined ? String(val) : "";
                                    break;
                            }
                        }

                        const matchRaw = val !== null && val !== undefined && String(val).toLowerCase().includes(query);
                        const matchFormatted = formattedVal && formattedVal.toLowerCase().includes(query);

                        return matchRaw || matchFormatted;
                    });
                });
            }

            // 4. Apply Sorting (from Sort module)
            const activeSorts = (this.options.columns || [])
                .filter(c => c.sortDirection && c.sortDirection !== 0)
                .sort((a, b) => (a.sortPriority || 0) - (b.sortPriority || 0));

            if (activeSorts.length > 0) {
                records.sort((a, b) => {
                    for (const col of activeSorts) {
                        const field = col.field;
                        const direction = col.sortDirection;

                        let valA = a[field];
                        let valB = b[field];

                        if (valA === null || valA === undefined) valA = "";
                        if (valB === null || valB === undefined) valB = "";

                        if (valA === valB) continue;

                        const numA = this.utils.parseNumber(valA);
                        const numB = this.utils.parseNumber(valB);

                        if (typeof numA === "number" && typeof numB === "number") {
                            return (numA - numB) * direction;
                        }

                        return String(valA).localeCompare(String(valB), undefined, {
                            numeric: true,
                            sensitivity: 'base'
                        }) * direction;
                    }
                    return 0;
                });
            }

            // 5. Update State and Render
            this.filteredRecords = records;
            await this.records.render(records);
            await this.records.computeAggregates();

            // 6. Sync UI States
            if (this.filter) {
                if (typeof this.filter.updateCachedItems === 'function') {
                    await this.filter.updateCachedItems();
                }
                if (typeof this.filter.updateButtonState === 'function') {
                    await this.filter.updateButtonState();
                }
            }
            if (this.sort?.updateButtonState) {
                await this.sort.updateButtonState();
            }

        } catch (err) {
            console.error("DataGrid: Error processing data:", err);
        }
    }

    /**
     * Render the grid records and activate UI enhancements.
     *
     * Rendering behavior:
     * - Uses `filteredRecords` if available
     * - Falls back to a deep clone of the original dataset
     * - Delegates table rendering to Records module
     * - Activates tooltips after DOM is updated
     *
     * @async
     * @returns {Promise<void>}
     */
    async render() {
        await this.records.render(this.filteredRecords);
        if (this.sort) {
            this.sort.updateButtonState();
        }
        await this.utils.triggerTooltips();
    }

    /**
     * Fetches records from the server using the defined URL.
     *
     * The method performs an HTTP GET request (or custom request if `fetchOptions` are provided),
     * handles loading state by adjusting the table container's opacity, and validates the response format.
     * It expects either an array `[...]` or an object containing a `data` property `{ data: [...] }`.
     *
     * @async
     * @function fetchRecords
     * @returns {Promise<Array>} A promise that resolves to an array of data records.
     */
    async fetchRecords() {
        if (!this.options.url) {
            console.warn("DataGrid: No URL defined for fetchRecords.");
            return [];
        }

        try {
            const tableContainer = document.getElementById(`table-container-${this.uniqueId}`);
            if (tableContainer) tableContainer.style.opacity = "0.5";

            const fetchConfig = { ...this.options.fetchOptions };

            if (fetchConfig.method) {
                const methodUpper = fetchConfig.method.toUpperCase();
                if (['GET', 'HEAD'].includes(methodUpper) && fetchConfig.body) {
                    console.warn(`DataGrid: Request with ${methodUpper} method cannot have body. Auto-changing to POST.`);
                    fetchConfig.method = 'POST';
                }
            } else {
                fetchConfig.method = fetchConfig.body ? 'POST' : 'GET';
            }

            const response = await fetch(this.options.url, fetchConfig);

            if (!response.ok) {
                console.error(`DataGrid Fetch Error: HTTP Error! status: ${response.status}`);
                if (tableContainer) tableContainer.style.opacity = "1";
                return [];
            }

            const result = await response.json();

            if (tableContainer) tableContainer.style.opacity = "1";
            if (Array.isArray(result.records)) {
                return result.records;
            } else {
                console.error("DataGrid: Unrecognized API response format. Expected Array or { data: [] }");
                return [];
            }
        } catch (error) {
            console.error("DataGrid Fetch Error:", error);
            const tableContainer = document.getElementById(`table-container-${this.uniqueId}`);
            if (tableContainer) tableContainer.style.opacity = "1";
            return [];
        }
    }


    /**
     * Set a global search query and refresh the grid.
     *
     * @async
     * @param {string} query - The search query.
     * @returns {Promise<void>}
     */
    async search(query) {
        this.options.query = String(query || "").trim();
        await this.processData();
    }

    /**
     * Refreshes the grid with new data and resets its state.
     *
     * This method replaces the current records, clears cached visible data,
     * resets row selection, filters, sorting, and aggregates,
     * then re-renders the grid.
     *
     * @async
     * @param {Array<Object>} passedRecords - The new records to load into the grid.
     * @returns {Promise<void>}
     */
    async refresh(passedRecords) {
        let newRecords = passedRecords;

        if (!newRecords && this.options.url) {
            newRecords = await this.fetchRecords();
        } else if (!newRecords) {
            newRecords = this.options.records;
        }

        this.options.records = newRecords;
        await this.processData();
    }

    /**
     * Adds a new row to the grid data and refreshes the grid.
     *
     * The record can be inserted either at the top or at the end of the data set.
     * After insertion, internal caches are reset and the grid is re-rendered
     * to reflect the updated data.
     *
     * @async
     * @param {Object} record - The record object to be added to the grid.
     * @param {boolean} [atTop=false] - Whether to insert the record at the beginning of the list.
     * @returns {Promise<void>}
     */
    async addRow(record, atTop = false) {
        if (!record || typeof record !== 'object') return;

        if (atTop) {
            this.options.records.unshift(record);
        } else {
            this.options.records.push(record);
        }

        this.filteredRecords = null;

        await this.refresh(this.options.records);
    }

    /**
     * Updates a specific row based on its primary key value.
     *
     * The method finds the target record using the configured index field,
     * merges the existing record with the provided partial values,
     * and refreshes the grid to reflect the changes.
     *
     * @async
     * @param {string|number} id - The primary key value of the row to update.
     * @param {Object} newValues - Partial data to merge into the existing row.
     * @returns {Promise<void>}
     */
    async updateRow(id, newValues) {
        const indexField = this.options.index || 'id';

        const rowIndex = this.options.records.findIndex(
            r => String(r[indexField]) === String(id)
        );

        if (rowIndex === -1) {
            console.warn(`DataGrid: Row with ID ${id} was not found.`);
            return;
        }

        this.options.records[rowIndex] = {
            ...this.options.records[rowIndex],
            ...newValues
        };

        await this.refresh(this.options.records);
    }

    /**
     * Removes a row from the grid based on its primary key value.
     *
     * The method filters out the record matching the given ID from the data source,
     * updates the internal selection state if necessary,
     * and refreshes the grid to reflect the removal.
     *
     * @async
     * @param {string|number} id - The primary key value of the row to remove.
     * @returns {Promise<void>}
     */
    async removeRow(id) {
        const indexField = this.options.index || 'id';

        const initialLength = this.options.records.length;
        this.options.records = this.options.records.filter(
            r => String(r[indexField]) !== String(id)
        );

        if (this.options.records.length === initialLength) {
            console.warn(`DataGrid: Row with ID ${id} was not found for removal.`);
            return;
        }

        if (this.selectedRows && this.selectedRows.has(String(id))) {
            this.selectedRows.delete(String(id));
        }

        await this.refresh(this.options.records);
    }

    /**
     * Returns the records currently visible in the grid.
     *
     * This includes the result after sorting and filtering have been applied.
     * A deep clone is returned to prevent external mutations from affecting
     * the internal grid state.
     *
     * @returns {Array<Object>} The list of visible records.
     */
    getVisibleRecords() {
        return this.utils.deepClone(
            this.filteredRecords || this.options.records || []
        );
    }

    /**
     * Resets the grid to its initial state.
     *
     * This clears the search input, filters, sorting, and row selections,
     * then refreshes the grid using the current original records.
     *
     * @async
     * @returns {Promise<void>}
     */
    async reset() {
        /** @type {HTMLInputElement|null} */
        this.options.query = "";
        await this.refresh(this.options.records);
    }

    /**
     * Destroys the DataGrid instance by cleaning up DOM elements,
     * clearing memory references, and stopping any pending asynchronous tasks.
     *
     * This method performs the following:
     * - Cancels pending timeouts or asynchronous processes.
     * - Clears the main DOM element and its child nodes.
     * - Empties internal data structures (records, selected rows, expanded rows).
     * - Removes references to submodules and options to free memory.
     * - Optionally nullifies the main element reference.
     */
    destroy() {
        // 1. Remove global variable reference
        if (this.element && this.element.id) {
            const id = this.element.id;
            if (window[id] === this) {
                delete window[id];
            }
        }

        // 2. Clear timeouts
        if (this.toolbar && this.toolbar._searchDebounce) {
            clearTimeout(this.toolbar._searchDebounce);
        }

        // 3. Dispose active tooltips
        if (this.utils && typeof this.utils.disposeTooltips === "function") {
            this.utils.disposeTooltips();
        }

        // 4. Clear DOM and classes
        if (this.element) {
            this.element.innerHTML = "";
            this.element.classList.remove("datagrid", "row", "row-cols-1", "g-3", "bg-light", "p-0", "m-0", "border-0");
            delete this.element.__dataGridInstance;
        }

        // 5. Clear internal data structures
        if (this.selectedRows) this.selectedRows.clear();
        if (this.records && this.records.expandedRows) this.records.expandedRows.clear();
        if (this.expandedRows) this.expandedRows.clear();

        this.options.records = [];
        this.filteredRecords = [];
        this.columnsByField = {};

        // 6. Nullify references
        this.utils = null;
        this.toolbar = null;
        this.column = null;
        this.records = null;
        this.filter = null;
        this.sort = null;
        this.options = null;
        this.element = null;
    }
}