/**
 * Column
 * Part of "Data Grid Library"
 * Provides UI and logic for showing/hiding columns, bulk selection,
 * searching column titles, and exporting column visibility to CSV.
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import DataGrid from "./DataGrid";

export class Column {

    /**
     * Static HTML template string for the column settings modal.
     * - Includes search input, bulk action buttons, and Apply button.
     * - Used to dynamically render the modal via DOMParser.
     */
    static get templateString() {
        return `
            <div class="modal" tabindex="-1">
                <div class="modal-dialog modal-dialog-scrollable" role="document">
                    <div class="modal-content border-0">
                        <div class="modal-header border-0">
                            <h6 class="modal-title fw-bolder">Show/Hide Columns</h6>
                            <button type="button" class="btn-close" data-coreui-dismiss="modal" aria-label="Close"></button>
                        </div>
                        <div class="modal-body">
                            <div class="row mb-3 g-1">
                                <div class="col">
                                    <input type="text" class="form-control form-control-sm rounded-pill shadow-none px-3 border-light-subtle bg-light search-form" placeholder="Search...">
                                </div>
                                <div class="col-auto">
                                    <button class="btn btn-light btn-sm select-all" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Select All"><i class="cil-check-alt icon fw-bolder"></i></button>
                                    <button class="btn btn-light btn-sm select-none" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Deselect All"><i class="cil-square icon fw-bolder"></i></button>
                                    <button class="btn btn-light btn-sm toggle-select" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Toggle Select"><i class="cil-swap-vertical icon fw-bolder"></i></button>
                                    <button class="btn btn-light btn-sm download-csv" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Save As CSV"><i class="cil-description icon fw-bolder"></i></button>
                                </div>
                            </div>
                        </div>
                        <div class="modal-footer bg-body-tertiary">
                            <small class="me-auto"><span class="selected-items"></span> of <span class="total-items"></span> columns selected</small>
                            <button class="btn btn-sm btn-dark fw-bolder apply-button"><i class="cil-send icon fw-bolder"></i> Apply</button>
                        </div>
                    </div>
                </div>
            </div>`;
    }

    /**
     * Constructor
     * @param {DataGrid} grid - Reference to the parent DataGrid instance.
     */
    constructor(grid) {
        this.grid = grid;
        this.uniqueId = this.grid.uniqueId;
        this.containerId = `column-modal-${this.uniqueId}`;
        this.searchKeyword = "";
        this.initialize();
    }

    /**
     * Initialize column definitions.
     * - Populates grid.ColumnsByField with references to each column.
     * - Does NOT overwrite the object (already created in DataGrid).
     */
    initialize() {
        const {columns} = this.grid.options || {};
        if (!Array.isArray(columns)) return;
        this.grid.columnsByField = this.grid.columnsByField || {};
        for (const column of columns) {
            if (!column?.field) continue;

            column.hidden = Boolean(column.hidden);
            const isFieldA = column.field === DataGrid.ACTION_COLUMN_ID;
            column.sortable = isFieldA ? false : column.sortable !== false;
            column.filterable = isFieldA ? false : column.filterable !== false;

            if (Array.isArray(column.styles)) {
                // keep as is
            } else {
                column.styles = column.styles && typeof column.styles === "string"
                    ? [column.styles]
                    : [];
            }

            this.grid.columnsByField[column.field] = column;
        }

        this.grid.options.columns = columns;
    }

    /**
     * Render the column settings modal.
     * - Builds modal from template string.
     * - Attaches event listeners for search, bulk actions, CSV export, and Apply.
     * - Appends column items and shows modal.
     * - Cleans up modal on close.
     */
    async render() {
        const parser = new DOMParser();
        const element = parser.parseFromString(Column.templateString, "text/html").body.firstElementChild;
        element.setAttribute("id", this.containerId);

        const input = element.querySelector(".search-form");
        input.addEventListener("input", (e) => {
            /** @type {HTMLInputElement} */
            const target = e.target;
            this.searchKeyword = (target.value || '').toLowerCase().trim();
            this.updateItems();
        });

        element.querySelector('.select-all').addEventListener('click', () => this.setVisibility("show"));
        element.querySelector('.select-none').addEventListener('click', () => this.setVisibility("hide"));
        element.querySelector('.toggle-select').addEventListener('click', () => this.setVisibility("toggle"));
        element.querySelector('.download-csv').addEventListener('click', () => this.downloadCSV());
        element.querySelector('.apply-button').addEventListener('click', async () => {
                try {
                    await this.grid.records.renderHeader();
                    await this.grid.records.render();
                    await this.grid.utils.triggerTooltips();
                } catch (err) {
                    console.error(err);
                }
                // noinspection JSUnresolvedReference
                if (typeof coreui !== "undefined" && coreui && coreui.Modal) {
                    coreui.Modal.getInstance(element)?.hide();
                }
            }
        );

        element.querySelector('div.modal-body').appendChild(this.createItems());
        // noinspection JSUnresolvedReference
        if (typeof coreui !== "undefined" && coreui && coreui.Modal) {
            const modal = new coreui.Modal(element, {backdrop: 'static'});
            modal.show(null);
        }
        this.updateCounts();
        element.addEventListener("hidden.coreui.modal", () => element.remove());
        await this.grid.utils.triggerTooltips();
    }

    /**
     * Update counts in modal footer.
     * - Shows the number of selected (visible) columns vs. total columns.
     */
    updateCounts() {
        const element = document.getElementById(this.containerId);
        if (element) {
            element.querySelector('.selected-items').textContent =
                (this.grid.options.columns.filter(column => !column.hidden).length).toString();
            element.querySelector('.total-items').textContent =
                (this.grid.options.columns.length).toString();
        }
    }

    /**
     * Create a list of column items based on the current query filter.
     * - Returns a list-group element containing checkboxes for each column.
     */
    createItems() {
        const columns = this.filterColumns(this.searchKeyword);
        const items = columns.map(column => this.createItem(column));
        return this.grid.utils.createElement("div", {
            classes: ["list-group", "list-group-flush"],
            children: items
        });
    }

    /**
     * Create a single column item with checkbox.
     * - Checkbox toggles the hidden state of the column.
     * - Label shows column title.
     */
    createItem(column) {
        const checkboxId = `checkbox-${this.containerId}__${column.field}`;
        const template = document.createElement("label");
        template.className = "list-group-item d-flex align-items-center gap-2 px-0";
        template.htmlFor = checkboxId;

        template.innerHTML = `
        <input type="checkbox" class="form-check-input flex-shrink-0" id="${checkboxId}">
        <span class="form-checked-content flex-grow-1 pt-1">${column.title}</span>
    `;

        const checkbox = template.querySelector("input");
        checkbox.addEventListener("change", () => this.select(column.field, checkbox.checked));
        if (!column.hidden) checkbox.checked = true;

        return template;
    }

    /**
     * Filter columns by query string.
     * - Matches against column title (case-insensitive).
     */
    filterColumns(query) {
        return this.grid.options.columns.filter(column =>
            column.title?.toLowerCase().includes(query?.toLowerCase())
        );
    }

    /**
     * Update visibility state for all non-mandatory columns.
     * @param {"show"|"hide"|"toggle"} mode
     */
    setVisibility(mode) {
        this.grid.options.columns.forEach(column => {
            switch (mode) {
                case "show":
                    column.hidden = false;
                    break;
                case "hide":
                    column.hidden = true;
                    break;
                case "toggle":
                    column.hidden = !column.hidden;
                    break;
            }
        });
        this.updateItems();
    }


    /**
     * Refresh the list of items in the modal body after changes.
     * - Replaces a list-group with updated items.
     * - Updates counts in footer.
     */
    updateItems() {
        const content = document.querySelector(`#${this.containerId} .modal-body`);
        const items = content?.querySelector(".list-group");
        if (items) items.replaceWith(this.createItems());
        this.updateCounts();
    }

    /**
     * Handle checkbox selection for a single column.
     * - Updates the hidden state of the column based on checkbox value.
     * - Recalculates counts in the modal footer.
     *
     * @param {string} field - The column field name.
     * @param {boolean} checked - True if the column should be visible, false if hidden.
     */
    select(field, checked) {
        this.grid.options.columns
            .filter(column => column.field === field)
            .forEach(column => column.hidden = !checked);
        this.updateCounts();
    }

    /**
     * Export current column visibility state to CSV.
     * - Includes only columns that are currently visible (not hidden).
     * - Reflects the current grid state (after filters/search/sort).
     * - Generates a CSV file with column names and visibility (show/hide).
     * - Uses Blob and ObjectURL to trigger a download in the browser.
     * - Filename is derived from a grid name, element id, or fallback string.
     */
    downloadCSV() {
        const filename = `${this.grid.options.name || this.grid.element?.id || 'columns-list'}-${Date.now()}`;
        const visibleColumns = (this.grid.options.columns || []).filter(col => !col.hidden);
        const header = `"COLUMN NAME","VISIBILITY"`;
        const rows = visibleColumns.map(col =>
            `"${(col.title || col.field || "").replace(/"/g, '""')}","show"`
        );

        const hiddenColumns = (this.grid.options.columns || []).filter(col => col.hidden);
        const hiddenRows = hiddenColumns.map(col =>
            `"${(col.title || col.field || "").replace(/"/g, '""')}","hide"`
        );

        const content = [header, ...rows, ...hiddenRows].join("\n");
        const blob = new Blob([content], {type: 'text/csv;charset=utf-8;'});
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = this.grid.utils.toKebabCase(`LIST COLUMNS ${filename}`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }
}