/**
 * Filter
 * Part of "Data Grid Library"
 *
 * Provides UI and logic for filtering grid records by column values.
 * Features:
 * - Modal-based UI with a searchable checkbox list
 * - Bulk selection (select all / none / toggle)
 * - CSV export of distinct values
 * - Multi-column filtering with priority handling
 * - Safe re-filtering from master records to prevent data loss
 *
 * @since 2025
 * @author antonsofyan@president.ac.id
 */

"use strict";

import DataGrid from "./DataGrid";

export class Filter {

    /**
     * Static HTML template for the filter modal.
     * Includes:
     * - Search input
     * - Bulk selection buttons
     * - CSV export button
     * - Apply and Clear buttons
     *
     * @returns {string}
     */
    static get templateString() {
        return `
        <div class="modal" tabindex="-1">
            <div class="modal-dialog modal-lg modal-dialog-scrollable">
                <div class="modal-content border-0">
                    <div class="modal-header border-0 pb-0">
                        <h6 class="modal-title fw-bolder"></h6>
                        <button type="button" class="btn-close" data-coreui-dismiss="modal" aria-label="Close"></button>
                    </div>
                    <div class="modal-body pb-0">
                        <div class="row mb-3 g-1 sticky-top bg-white pb-2">
                            <div class="col">
                                <input type="text" class="form-control form-control-sm rounded-pill shadow-none px-3 border-light-subtle bg-light search-form" placeholder="Search...">
                            </div>
                            <div class="col-auto">
                                <button class="btn btn-light btn-sm select-all" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Select All"><i class="cil-check-alt icon fw-bolder"></i></button>
                                <button class="btn btn-light btn-sm select-none" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Deselect All"><i class="cil-square icon fw-bolder"></i></button>
                                <button class="btn btn-light btn-sm toggle-select" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Toggle Select"><i class="cil-swap-vertical icon fw-bolder"></i></button>
                                <button class="btn btn-light btn-sm download-csv" data-coreui-toggle="tooltip" data-coreui-placement="bottom" title="Save As CSV"><i class="cil-description icon fw-bolder"></i></button>
                            </div>
                        </div>
                        
                        <div class="filter-items-container" style="max-height: 400px; overflow-y: auto; overflow-x: hidden;">
                            <div class="items-placeholder"></div>
                        </div>
                    </div>
                    <div class="modal-footer bg-light-subtle py-1">
                        <small class="text-center w-100 text-dark">Select a checkbox to filter rows</small>
                    </div>
                    <div class="modal-footer bg-body-tertiary">
                        <small class="me-auto"><span class="selected-items"></span> of <span class="total-items"></span> items selected</small>
                        <button class="btn btn-sm btn-light fw-bolder clear-button"><i class="cil-sync icon fw-bolder"></i> Clear Filter</button>
                        <button class="btn btn-sm btn-dark fw-bolder filter-button"><i class="cil-send icon fw-bolder"></i> Apply Filter</button>
                    </div>
                </div>
            </div>
        </div>`;
    }

    /**
     * @param {DataGrid} grid - Reference to the parent DataGrid instance.
     *
     * @property {DataGrid} grid - Parent DataGrid instance.
     * @property {string} uniqueId - Unique grid identifier.
     * @property {string} containerId - DOM id for the filter modal.
     * @property {string} query - Current search query inside the modal.
     * @property {string} filterBy - Column field currently being filtered.
     * @property {Object<string, Object<string, Array<number>>>} cacheItems
     * Cached distinct values per column mapped to record IDs.
     * @property {Object<string, Array<string>>} filteredItems
     * Selected filter values per column.
     * @property {HTMLElement|null} _modalElement - Active modal DOM element.
     * @property {number|null} _searchDebounce - Debounce timer reference.
     */
    constructor(grid) {
        this.grid = grid;
        this.uniqueId = grid.uniqueId;
        this.containerId = `filter-modal-${this.uniqueId}`;
        this.searchKeyword = "";
        this.filterBy = "";
        this.cacheItems = {};
        this.filteredItems = {};
        this._modalElement = null;
        this._searchDebounce = null;
        this.initialize().catch();
    }

    /**
     * Initialize filter module.
     * - Prepares filteredItems structure.
     * - Builds initial cache from current records.
     *
     * @returns {Promise<void>}
     */
    async initialize() {
        await this.prepareFilterStructures();
        await this.updateCachedItems();
    }

    /**
     * Initialize filteredItems arrays for all filterable columns.
     *
     * @returns {Promise<void>}
     */
    async prepareFilterStructures() {
        (this.grid.options.columns || []).forEach((column) => {
            if (column && column.field !== DataGrid.ACTION_COLUMN_ID) {
                if (!Array.isArray(this.filteredItems[column.field])) {
                    this.filteredItems[column.field] = [];
                }
            }
        });
    }

    /**
     * Build a cache of distinct values per column.
     *
     * Structure:
     * cacheItems[field][value] = [recordId1, recordId2, ...]
     *
     * Uses current Records.filteredRecords to stay in sync
     * with global search and existing filters.
     *
     * @returns {Promise<void>}
     */
    async updateCachedItems() {
        const columns = this.grid.options.columns || [];
        const indexField = this.grid.options.index || 'id';
        const records = Array.isArray(this.grid.records.filteredRecords) ? this.grid.records.filteredRecords : [];
        this.cacheItems = {};

        for (const record of records) {
            for (const column of columns) {
                if (!column || column.field === DataGrid.ACTION_COLUMN_ID) continue;
                const field = column.field;
                if (!this.cacheItems[field]) this.cacheItems[field] = {};

                const rawValue = record[field];
                const valueKey = rawValue === null || rawValue === undefined ? "" : String(rawValue);

                if (!this.cacheItems[field][valueKey]) this.cacheItems[field][valueKey] = [];
                if (!this.cacheItems[field][valueKey].includes(record[indexField])) {
                    this.cacheItems[field][valueKey].push(record[indexField]);
                }
            }
        }
    }

    /**
     * Render filter modal for a specific column.
     * - Builds modal DOM
     * - Attaches event listeners
     * - Displays modal
     * - Cleans up on close
     *
     * @param {string} filterBy - Column field name to filter.
     * @returns {Promise<void>}
     */
    async render(filterBy) {
        this.filterBy = filterBy;

        const element = this.createModalElement();
        if (!element) return;
        this._modalElement = element;
        document.body.appendChild(element);
        // noinspection JSUnresolvedReference
        const modal = (typeof coreui !== "undefined" && coreui && typeof coreui.Modal === "function")
            ? new coreui.Modal(element, { backdrop: 'static' })
            : null;
        if (modal) modal.show(null);
        this.updateCounts();
        element.addEventListener("hidden.coreui.modal", () => {
            element.remove();
            if (this._modalElement === element) this._modalElement = null;
        });

        await this.grid.utils.triggerTooltips();
    }

    /**
     * Create a modal element from template string.
     * - Sets title based on column
     * - Attaches UI event listeners
     * - Appends a distinct value list
     *
     * @private
     * @returns {HTMLElement|null}
     */
    createModalElement() {
        const parser = new DOMParser();
        const element = parser.parseFromString(Filter.templateString, "text/html").body.firstElementChild;
        if (!element) return null;

        element.setAttribute("id", this.containerId);

        const columnsByField = this.grid.columnsByField || {};
        const columnTitle = columnsByField[this.filterBy]?.title || this.filterBy || "Column";
        element.querySelector('.modal-title').innerHTML =
            `Local Filter For <span class="text-danger">'${columnTitle}'</span>`;

        const input = element.querySelector(".search-form");
        if (input) {
            input.addEventListener("input", (e) => {
                clearTimeout(this._searchDebounce);
                this._searchDebounce = setTimeout(() => {
                    /** @type {HTMLInputElement} */
                    const target = e.target;
                    this.searchKeyword = String(target.value || "").toLowerCase().trim();
                    this.updateItems();
                }, 200);
            });
            input.addEventListener("keydown", (e) => {
                if (e.key === "Escape") {
                    input.value = "";
                    this.searchKeyword = "";
                    this.updateItems();
                }
            });
        }

        element.querySelector('.select-all')?.addEventListener('click', () => this.updateSelection('all'));
        element.querySelector('.select-none')?.addEventListener('click', () => this.updateSelection('none'));
        element.querySelector('.toggle-select')?.addEventListener('click', () => this.updateSelection('toggle'));
        element.querySelector('.download-csv')?.addEventListener('click', () => this.downloadCSV());
        element.querySelector('.filter-button')?.addEventListener('click', () => this.applyFilter());
        element.querySelector('.clear-button')?.addEventListener('click', () => this.clear(this.filterBy));
        element.querySelector('.items-placeholder')?.replaceWith(this.createItems());
        return element;
    }

    /**
     * Update the selection state for the active column.
     * Supports bulk actions:
     * - "all" → select all values
     * - "none" → deselect all values
     * - "toggle" → invert selection
     *
     * @param {"all"|"none"|"toggle"} action
     * @returns {void}
     */
    updateSelection(action) {
        const field = this.filterBy;
        if (!field) return;
        const available = this.cacheItems[field] ? Object.keys(this.cacheItems[field]).map(k => String(k)) : [];
        if (!Array.isArray(this.filteredItems[field])) this.filteredItems[field] = [];

        switch (action) {
            case 'all':
                this.filteredItems[field] = [...available];
                break;
            case 'none':
                this.filteredItems[field] = [];
                break;
            case 'toggle':
                this.filteredItems[field] = available.filter(item => !this.filteredItems[field].includes(item));
                break;
        }
        this.updateItems();
        this.updateCounts();
    }

    /**
     * Update selected vs. total item counts in the modal footer.
     *
     * @returns {void}
     */
    updateCounts() {
        const el = this._modalElement || document.getElementById(this.containerId);
        if (!el) return;
        const items = this.cacheItems[this.filterBy] || {};
        const selectedCount = (this.filteredItems[this.filterBy] || []).length;
        const totalCount = Object.keys(items).length;
        el.querySelector('.selected-items').textContent = String(selectedCount);
        el.querySelector('.total-items').textContent = String(totalCount);
    }

    /**
     * Create a list-group of distinct values for the active column.
     * Applies search query filtering.
     *
     * @private
     * @returns {HTMLElement}
     */
    createItems() {
        const field = this.filterBy;
        const cacheForField = this.cacheItems[field] || {};
        const keys = Object.keys(cacheForField).map(k => String(k));
        const filteredKeys = keys.filter(key => key.toLowerCase().includes(this.searchKeyword));
        filteredKeys.sort((a, b) => {
            return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        });
        const children = filteredKeys.map(key => this.createItem(key, cacheForField[key] || []));
        return this.grid.utils.createElement("div", {
            classes: ["list-group", "list-group-flush"],
            children
        });
    }

    /**
     * Create a single checkbox item.
     * - Checkbox toggles inclusion in filteredItems
     * - Badge shows record count for the value
     *
     * @private
     * @param {string} item - Distinct value.
     * @param {Array<number>} records - Record IDs containing the value.
     * @returns {HTMLElement}
     */
    createItem(item, records) {
        const safeKey = this.grid.utils.toKebabCase ? this.grid.utils.toKebabCase(String(item)) : String(item).replace(/[^a-z0-9-_]/gi, '-');
        const checkboxId = `checkbox-${this.containerId}__${safeKey}`;

        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.className = "form-check-input flex-shrink-0";
        checkbox.id = checkboxId;
        checkbox.value = String(item);
        checkbox.addEventListener("change", e => this.select(e));
        if (this.filteredItems[this.filterBy].includes(String(item))) {
            checkbox.checked = true;
        }

        const content = document.createElement("span");
        content.className = "form-checked-content flex-grow-1 pt-1";
        content.textContent = String(item);

        const badge = document.createElement("span");
        badge.className = "badge text-bg-light ms-auto";
        badge.textContent = String(records.length);

        const label = document.createElement("label");
        label.className = "list-group-item d-flex align-items-center gap-2 px-0";
        label.htmlFor = checkboxId;
        label.append(checkbox, content, badge);
        return label;
    }

    /**
     * Refresh the item list inside the modal after search or selection changes.
     *
     * @private
     * @returns {void}
     */
    updateItems() {
        const el = this._modalElement || document.getElementById(this.containerId);
        if (!el) return;
        const container = el.querySelector(".filter-items-container");
        const items = container?.querySelector(".list-group");

        if (items) {
            items.replaceWith(this.createItems());
        } else if (container) {
            container.appendChild(this.createItems());
        }

        this.updateCounts();
    }

    /**
     * Handle checkbox toggle for a single value.
     *
     * @param {Event} e - Change event.
     * @returns {void}
     */
    select(e) {
        /** @type {HTMLInputElement} */
        const target = e.target;
        const item = String(target.value);
        const checked = !!target.checked;
        const field = this.filterBy;
        if (!field) return;
        if (!Array.isArray(this.filteredItems[field])) this.filteredItems[field] = [];

        const selectedItems = this.filteredItems[field];
        const idx = selectedItems.indexOf(item);
        if (checked && idx === -1) selectedItems.push(item);
        if (!checked && idx >= 0) selectedItems.splice(idx, 1);

        this.updateItems();
        this.updateCounts();
    }

    /**
     * Applies active filters to the grid.
     *
     * Workflow:
     * 1. Validates the target column and updates filter priorities.
     * 2. Triggers the centralized data processing pipeline (grid.processData()).
     * 3. Manages the UI update sequence to prevent race conditions by waiting
     *    for the modal to fully close before processing.
     *
     * @async
     * @returns {Promise<void>}
     */
    async applyFilter() {
        const filterBy = this.filterBy;
        const columns = this.grid.options.columns || [];

        if (!this.filteredItems) {
            this.filteredItems = {};
        }

        const columnsByField = this.grid.columnsByField || {};
        const col = columnsByField[filterBy] || columns.find(c => c.field === filterBy);

        if (col && col.hidden) {
            console.warn(`Filter ignored: column "${filterBy}" is hidden`);
            return;
        }
        if (!col) {
            console.warn(`Filter warning: column "${filterBy}" not found`);
            return;
        }

        if (this.grid.utils.isDefined(filterBy)) {
            const existingCount = columns.filter(c => c && c.filterPriority && c.filterPriority !== 0).length;
            if (!col.filterPriority) {
                col.filterPriority = existingCount + 1;
            }
            this.grid.utils.normalizePriorities(columns, "filter");
        }

        const modalEl = document.getElementById(this.containerId);
        let modalInstance = null;
        // noinspection JSUnresolvedReference
        if (typeof coreui !== "undefined" && coreui && coreui.Modal && modalEl) {
            // noinspection JSUnresolvedReference
            modalInstance = coreui.Modal.getInstance(modalEl);
        }

        const performRender = async () => {
            await this.grid.processData();

            if (this.grid.utils && typeof this.grid.utils.triggerTooltips === 'function') {
                await this.grid.utils.triggerTooltips();
            }
        };

        if (modalInstance) {
            modalEl.addEventListener('hidden.coreui.modal', async () => {
                await performRender();
            }, { once: true });

            modalInstance.hide();
        } else {
            await performRender();
        }
    }

    /**
     * Clear filter state.
     *
     * Behavior:
     * - If filterBy is provided → clears that column only
     * - If omitted → clears all filters
     * - Triggers grid.processData() to recalculate the state
     *
     * @param {string} [filterBy] - Optional column field.
     * @returns {Promise<void>}
     */
    async clear(filterBy) {
        if (this.grid.utils.isDefined(filterBy)) {
            this.filteredItems[filterBy] = [];
            const col = (this.grid.options.columns || []).find(c => c.field === filterBy);
            if (col) col.filterPriority = 0;
        } else {
            Object.keys(this.filteredItems).forEach(field => {
                this.filteredItems[field] = [];
                const col = (this.grid.options.columns || []).find(c => c.field === field);
                if (col) col.filterPriority = 0;
            });
        }

        this.grid.utils.normalizePriorities(this.grid.options.columns, "filter");
        this.filterBy = "";

        await this.grid.processData();

        const modalEl = document.getElementById(this.containerId);
        if (typeof coreui !== "undefined" && coreui && coreui.Modal && modalEl) {
            try {
                coreui.Modal.getInstance(modalEl)?.hide();
            } catch (err) {
                console.error("Modal hide error", err);
            }
        }
    }


    /**
     * Export distinct values of the active column to CSV.
     * - Uses current filtered dataset
     * - Includes value counts
     * - Escapes values safely
     *
     * @returns {void}
     */
    downloadCSV() {
        const filterBy = this.filterBy;
        const col = this.grid.columnsByField?.[filterBy];
        if (!col) {
            console.error("No column selected for CSV export");
            return;
        }

        const columnTitle = col.title || filterBy;
        const dataset = Array.isArray(this.grid.records?.filteredRecords)
            ? this.grid.records.filteredRecords
            : (this.grid.options.records || []);

        const valueMap = {};
        for (const record of dataset) {
            const rawValue = record?.[filterBy];
            const valueKey = rawValue === null || rawValue === undefined ? "" : String(rawValue);
            if (!valueMap[valueKey]) valueMap[valueKey] = 0;
            valueMap[valueKey]++;
        }

        const escape = (v) => `"${String(v).replace(/"/g, '""')}"`;
        let content = `${escape(columnTitle.toUpperCase())},TOTAL\n`;
        for (const [val, count] of Object.entries(valueMap)) {
            content += `${escape(val)},${count}\n`;
        }

        const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;

        const filename = `${this.grid.options.name || this.grid.element?.id || 'grid'}-${Date.now()}`;
        link.download = this.grid.utils.toKebabCase(`LIST DISTINCT ${columnTitle} FROM ${filename} TABLE`);

        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }


    /**
     * Update the visual state of filter buttons in the table header.
     * - Active filters → dark button
     * - Inactive → ghost-light button
     *
     * @returns {Promise<void>}
     */
    async updateButtonState() {
        const uniqueId = this.grid.uniqueId;
        const columns = this.grid.options.columns || [];
        const filteredItems = this.filteredItems || {};

        for (const col of columns) {
            if (!col?.filterable) continue;
            const field = col.field;
            const columnsByField = (this.grid.columnsByField || {})[field];
            if (!field || field === DataGrid.ACTION_COLUMN_ID || columnsByField?.hidden) continue;

            const btnId = `filter-rows-${field}-${uniqueId}`;
            const element = document.getElementById(btnId);
            if (!element) continue;

            const isActive = Array.isArray(filteredItems[field]) && filteredItems[field].length > 0;

            element.className = isActive
                ? "btn btn-dark text-white btn-sm"
                : "btn btn-light btn-sm";
        }
    }
}